package main

import (
 "bytes"
 "flag"
 "fmt"
 "io"
 "log"
 "os"
 "path/filepath"
 "strings"
)

type options struct {
 generated, formatting, list, recursive, unused, separate, aliases, status, cache bool
 company, excludes, file, local, output, project, order string
 groups []string
}

const defaultOrder = "std,general,company,project"
const stdinName = "<standard-input>"
const versionString = "3.0.0-20260611193416-a37f51062178"

func parseOptions() (options, []string) {
 var o options
 var ver, verOnly bool
 flag.BoolVar(&o.generated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
 flag.StringVar(&o.company, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
 flag.StringVar(&o.excludes, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
 flag.StringVar(&o.file, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
 flag.BoolVar(&o.formatting, "format", false, "Option will perform additional formatting. Optional parameter.")
 flag.StringVar(&o.order, "imports-order", defaultOrder, "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
 flag.BoolVar(&o.list, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
 flag.StringVar(&o.local, "local", "", "Deprecated")
 flag.StringVar(&o.output, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter. (default \"file\")")
 // The flag package supplies the default annotation itself.
 flag.Lookup("output").Usage = strings.TrimSuffix(flag.Lookup("output").Usage, " (default \"file\")")
 flag.StringVar(&o.project, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
 flag.BoolVar(&o.recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
 flag.BoolVar(&o.unused, "rm-unused", false, "Remove unused imports. Optional parameter.")
 flag.BoolVar(&o.separate, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
 flag.BoolVar(&o.aliases, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
 flag.BoolVar(&o.status, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
 flag.BoolVar(&o.cache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
 flag.BoolVar(&ver, "version", false, "Show version information")
 flag.BoolVar(&verOnly, "version-only", false, "Show only the version string")
 flag.Parse()
 if verOnly { fmt.Println(versionString); os.Exit(0) }
 if ver {
  fmt.Printf("version: %s\nbuilt with: go1.26.0\ntag: v%s\ncommit: n/a\nsource: github.com/incu6us/goimports-reviser/v3\n", versionString, versionString)
  os.Exit(0)
 }
 paths := append([]string(nil), flag.Args()...)
 if o.file != "" { paths = append(paths, o.file) }
 if len(paths) == 0 { flag.Usage(); log.Fatal("no file(s) or directory(ies) specified on input") }
 if len(paths)==1 && paths[0]=="-" { paths[0]=stdinName }
 if o.order=="" { o.order=defaultOrder }
 valid := map[string]bool{"std":true,"general":true,"company":true,"project":true,"blanked":true,"dotted":true}
 found := map[string]bool{}
 for _, s := range strings.Split(o.order,",") {
  s=strings.TrimSpace(s)
  if !valid[s] { flag.Usage(); log.Fatalf("unknown order group type: %q",s) }
  o.groups=append(o.groups,s); found[s]=true
 }
 if !found["std"] || !found["general"] || !found["company"] || !found["project"] {
  flag.Usage(); log.Fatalf("use default at least 4 parameters to sort groups of your imports: %q",defaultOrder)
 }
 return o, paths
}

func main() {
 o, paths:=parseOptions()
 log.Printf("Paths: %v",paths)
 changed:=false
 for _, p:=range paths {
  log.Printf("Processing %s",p)
  opt:=o
  if opt.project=="" {
   name,err:=projectFor(p)
   if err!=nil { flag.Usage(); log.Fatalf("Could not determine project name for path %s: %v",p,err) }
   opt.project=name
  }
  real:=p
  if real=="./..." { real="."; opt.recursive=true }
  st,err:=os.Stat(real)
  if err==nil && st.IsDir() && p!=stdinName {
   diff,err:=processDirectory(real,opt)
   if err!=nil {
    if opt.list { log.Fatalf("Failed to find unformatted files %s: %v",p,err) }
    log.Fatalf("Failed to fix directory %s: %v",p,err)
   }
   if len(diff)>0 { changed=true }
   if opt.list {
    for _,name:=range diff {fmt.Println(name)}
    if opt.status && len(diff)>0 {os.Exit(1)}
    return
   }
   continue
  }
  name:=p
  var data []byte
  if p==stdinName {data,err=io.ReadAll(os.Stdin)} else {
   name,err=filepath.Abs(p)
   if err==nil { data,err=os.ReadFile(name) }
  }
  if err!=nil { log.Fatalf("Failed to fix file: %v",err) }
  result,err:=revise(name,data,opt)
  if err!=nil { log.Fatalf("Failed to fix file: %v",err) }
  isDiff:=!bytes.Equal(data,result)
  changed=changed||isDiff
  if p!=stdinName && opt.output!="file" && opt.output!="write" && opt.output!="stdout" {
   log.Fatalf("invalid output %q specified",opt.output)
  }
  if opt.list {
   if isDiff { fmt.Println(name) }
   if p!=stdinName && opt.output=="write" {
    if err=writeFile(name,result);err!=nil { log.Fatalf("Failed to write file: %v",err) }
   }
  } else if p==stdinName || opt.output=="stdout" {
   if _,err=os.Stdout.Write(result);err!=nil {log.Fatal(err)}
  } else {
   if err=writeFile(name,result);err!=nil {log.Fatalf("Failed to write file: %v",err)}
  }
 }
 deprecated:=false
 if o.file!="" {
  log.Print("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
  deprecated=true
 }
 if o.local!="" {
  log.Print("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
  deprecated=true
 }
 if deprecated {log.Fatal("All changes to file are applied, but command-line syntax should be fixed")}
 if o.status && changed { os.Exit(1) }
}

func writeFile(name string,data []byte) error {
 return os.WriteFile(name,data,0644)
}

func processDirectory(dir string,o options) ([]string,error) {
 abs,err:=filepath.Abs(dir);if err!=nil{return nil,err}
 var diff []string
 patterns:=[]string{".git", ".idea"}
 if o.excludes!="" {patterns=append(patterns,strings.Split(o.excludes,",")...)}
 err=filepath.WalkDir(abs,func(p string,d os.DirEntry,walkErr error) error {
  if walkErr!=nil {return walkErr}
  if p==abs {return nil}
  rel,e:=filepath.Rel(abs,p);if e!=nil{return e}
  for _,pat:=range patterns {
   pat=strings.TrimSuffix(pat,"/")
   matched,_:=filepath.Match(pat,rel)
   if matched {
    if d.IsDir(){return filepath.SkipDir};return nil
   }
  }
  if d.IsDir(){if !o.recursive{return filepath.SkipDir};return nil}
  if !strings.HasSuffix(d.Name(),".go"){return nil}
  data,e:=os.ReadFile(p);if e!=nil{return fmt.Errorf("failed to fix %s: %w",p,e)}
  result,e:=revise(p,data,o)
  if e!=nil{return fmt.Errorf("failed to fix %s: %w",p,e)}
  if !bytes.Equal(data,result){diff=append(diff,p)}
  if !o.list { if e=writeFile(p,result);e!=nil{return fmt.Errorf("failed to fix %s: %w",p,e)} }
  return nil
 })
 if err!=nil{return nil,fmt.Errorf("failed to walk dif: %w",err)}
 return diff,nil
}
EOF
cat > src/module.go <<'EOF'
package main

import (
 "bufio"
 "fmt"
 "os"
 "path/filepath"
 "strconv"
 "strings"
)

// Search within the path supplied by the user, without implicitly extending a
// relative path to ancestors of the current working directory.
func projectFor(target string) (string,error) {
 if target==stdinName || target=="./..." { target="." }
 dir:=filepath.Clean(target)
 if info,err:=os.Stat(dir);err!=nil || !info.IsDir(){dir=filepath.Dir(dir)}
 for {
  mod:=filepath.Join(dir,"go.mod")
  data,err:=os.ReadFile(mod)
  if err==nil{return moduleName(data)}
  parent:=filepath.Dir(dir)
  if dir=="." || parent==dir {return "",err}
  dir=parent
 }
}

func moduleName(data []byte) (string,error) {
 s:=bufio.NewScanner(strings.NewReader(string(data)))
 var name string
 line:=0
 for s.Scan(){
  line++
  text:=strings.TrimSpace(s.Text())
  if i:=strings.Index(text,"//");i>=0{text=strings.TrimSpace(text[:i])}
  words:=strings.Fields(text)
  if len(words)==0 {continue}
  if words[0]=="module" {
   if name!="" {return "",fmt.Errorf("go.mod:%d: repeated module statement",line)}
   if len(words)!=2 {return "",fmt.Errorf("go.mod:%d: usage: module module/path",line)}
   name=words[1]
   if strings.HasPrefix(name,"\"") || strings.HasPrefix(name,"`") {
    x,e:=strconv.Unquote(name);if e==nil{name=x}
   }
  }
 }
 if name=="" {return "",fmt.Errorf("module is undefined")}
 return name,nil
}
