)

type importEntry struct {
 path, raw, alias, comment string
 spec *ast.ImportSpec
 group string
}
type sourceEdit struct { start,end int; text string }

func parseSource(name string,data []byte)(*token.FileSet,*ast.File,error){
 fs:=token.NewFileSet()
 f,err:=parser.ParseFile(fs,name,data,parser.ParseComments)
 if err!=nil {
  if list,ok:=err.(scanner.ErrorList);ok && len(list)>0 {err=list[0]}
  if len(data)==0{return fs,f,fmt.Errorf("file is empty and cannot be parsed as Go source, use -excludes flag to skip this file: %w",err)}
