}

func revise(name string,data []byte,o options)([]byte,error){
 fs,f,err:=parseSource(name,data)
 if err!=nil{return nil,err}
 if !o.generated && ast.IsGenerated(f){return data,nil}

 names:=map[string]string{}
 if o.aliases || o.unused {
  dir:=filepath.Dir(name)
  if name==stdinName {dir="."}
  names,err=loadPackageNames(dir,name==stdinName)
  if err!=nil{return nil,err}
 }
 var decls []*ast.GenDecl
 cgo:=map[*ast.GenDecl]bool{}
 var entries []*importEntry
 for _,d:=range f.Decls {
  g,ok:=d.(*ast.GenDecl)
  if !ok || g.Tok!=token.IMPORT{continue}
  if !g.Lparen.IsValid() && len(g.Specs)==1 {
   s:=g.Specs[0].(*ast.ImportSpec)
   p,_:=strconv.Unquote(s.Path.Value)
   if p=="C" {cgo[g]=true;continue}
  }
  decls=append(decls,g)
  for _,s:=range g.Specs {
   sp:=s.(*ast.ImportSpec)
   p,e:=strconv.Unquote(sp.Path.Value);if e!=nil{p=strings.Trim(sp.Path.Value,"\"`")}
   x:=&importEntry{path:p,raw:sp.Path.Value,spec:sp}
   if sp.Name!=nil{x.alias=sp.Name.Name}
   if sp.Comment!=nil {
    var parts []string
    for _,c:=range sp.Comment.List{parts=append(parts,c.Text)}
    x.comment=strings.Join(parts,"\n")
   }
   entries=append(entries,x)
  }
 }
 // Import names are looked up even for ordinary, non-versioned packages: an
 // explicit alias is required whenever the package's declared name differs
 // from the last component of its import path.
 if o.aliases {
  for _,x:=range entries {
   if x.alias=="" {if n:=names[x.path];n!="" && n!=path.Base(x.path){x.alias=n}}
  }
 }
 if o.unused {
  uses:=map[string]bool{}
  ast.Inspect(f,func(n ast.Node)bool{
   if s,ok:=n.(*ast.SelectorExpr);ok {if id,ok:=s.X.(*ast.Ident);ok {uses[id.Name]=true}}
   return true
  })
  keepAll:=false
  for _,x:=range entries {if x.alias=="_" || x.alias=="." {keepAll=true}}
  if !keepAll {
   kept:=entries[:0]
   for _,x:=range entries {
    n:=x.alias
    if n=="" {n=names[x.path];if n==""{n=path.Base(x.path)}}
    if uses[n]{kept=append(kept,x)}
   }
   entries=kept
  }
 }
 ranks:=map[string]int{}
 for i,g:=range o.groups{ranks[g]=i}
 has:=func(g string)bool{_,ok:=ranks[g];return ok}
 company:=[]string{}
 if o.company!="" {company=strings.Split(o.company,",")}
 if o.local!="" {company=append(company,strings.Split(o.local,",")...)}
 for _,x:=range entries {
  p:=strings.Trim(x.raw,"\"")
  x.group="general"
  if standardPackages[p] {x.group="std"} else {
   for _,prefix:=range company {if strings.HasPrefix(p,strings.TrimSpace(prefix)){x.group="company";break}}
   project:=strings.TrimSuffix(o.project,"/")
   if p==project || strings.HasPrefix(p,project+"/"){x.group="project"}
  }
  if x.alias=="_" && has("blanked"){x.group="blanked"}
  if x.alias=="." && has("dotted"){x.group="dotted"}
 }
 sort.SliceStable(entries,func(i,j int)bool{
  a,b:=entries[i],entries[j]
  if ranks[a.group]!=ranks[b.group]{return ranks[a.group]<ranks[b.group]}
  if o.separate && (a.alias=="")!=(b.alias==""){return a.alias==""}
  if a.path!=b.path{return a.path<b.path}
  return a.alias<b.alias
 })
 // Duplicate declarations do not survive the import rewrite, even when they
 // had distinct comments.  Keep the first occurrence.
 seen:=map[string]bool{}
 distinct:=entries[:0]
 for _,x:=range entries{
  key:=x.path+"\x00"+x.alias
  if seen[key]{continue};seen[key]=true
  distinct=append(distinct,x)
 }
 entries=distinct

 var edits []sourceEdit
 off:=func(p token.Pos)int{return fs.Position(p).Offset}
 if len(decls)>0 {
  first:=decls[0]
  block:=first.Lparen.IsValid() || len(entries)>1
  text:=""
  if len(entries)==0 {
   if len(cgo)>0{text="import ()"}
  } else if !block {
   text="import "+entryText(entries[0])
   if entries[0].comment!="" {
    // The trailing comment of a single import is retained in both locations
    // by the import rewriter.
    text+="\t"+entries[0].comment
   }
  } else {
   var b strings.Builder
   b.WriteString("import (\n")
   for i,x:=range entries {
    if i>0 && (x.group!=entries[i-1].group || (o.separate && (x.alias=="")!=(entries[i-1].alias==""))){b.WriteByte('\n')}
    b.WriteByte('\t');b.WriteString(entryText(x));b.WriteByte('\n')
   }
   b.WriteByte(')');text=b.String()
  }
  for i,g:=range decls {
   start,end:=off(g.Pos()),off(g.End())
   if i>0 && g.Doc!=nil{start=off(g.Doc.Pos())}
   if !g.Lparen.IsValid() && len(g.Specs)>0 {
    sp:=g.Specs[0].(*ast.ImportSpec)
    if sp.Comment!=nil && (len(entries)>0 || i>0){end=off(sp.Comment.End())}
   }
   replacement:="";if i==0{replacement=text}
   edits=append(edits,sourceEdit{start,end,replacement})
  }
 }
 out:=applyEdits(data,edits)
 out,err=format.Source(out)
 if err!=nil {return nil,err}
 if o.formatting {
  out,err=separateDeclarations(out)
  if err!=nil{return nil,err}
 }
 return out,nil
}

func entryText(x *importEntry)string {
 s:=""
 if x.alias!=""{s=x.alias+" "}
 s+=strconv.Quote(x.path)
 if x.comment!=""{s+=" "+x.comment}
 return s
}

func applyEdits(data []byte,edits []sourceEdit)[]byte {
 if len(edits)==0{return append([]byte(nil),data...)}
 sort.SliceStable(edits,func(i,j int)bool{return edits[i].start<edits[j].start})
 var b bytes.Buffer
 last:=0
 for _,e:=range edits {
  if e.start<last {continue}
  b.Write(data[last:e.start]);b.WriteString(e.text);last=e.end
 }
 b.Write(data[last:]);return b.Bytes()
}

func separateDeclarations(data []byte)([]byte,error){
 fs:=token.NewFileSet();f,err:=parser.ParseFile(fs,"",data,parser.ParseComments)
 if err!=nil{return nil,err}
 var edits []sourceEdit
 for i:=1;i<len(f.Decls);i++ {
  d:=f.Decls[i];p:=d.Pos()
  switch g:=d.(type){case *ast.GenDecl:if g.Doc!=nil{p=g.Doc.Pos()};case *ast.FuncDecl:if g.Doc!=nil{p=g.Doc.Pos()}}
  prev:=f.Decls[i-1]
  prevLine:=fs.Position(prev.End()).Line
  skip:=false
  for _,c:=range f.Comments {if fs.Position(c.Pos()).Line==prevLine && c.Pos()>=prev.End(){skip=true;break}}
  if skip{continue}
  pos:=fs.Position(p)
  if pos.Line<=prevLine+1 {edits=append(edits,sourceEdit{pos.Offset,pos.Offset,"\n"})}
 }
 return format.Source(applyEdits(data,edits))
}
