package main

import (
 "bytes"
 "encoding/json"
 "fmt"
 "io"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
)

type packageError struct { Pos, Err string }
type packageInfo struct {
 Dir,ImportPath,Name string
 GoFiles,CompiledGoFiles,Imports []string
 Error *packageError
 DepsErrors []*packageError
}

// Ask the language toolchain for package declarations and load errors; no
// source transformation is delegated to it.
func loadPackageNames(dir string,stdin bool)(map[string]string,error){
 cmd:=exec.Command("go","list","-e","-json","-deps",".")
 cmd.Dir=dir
 var stderr bytes.Buffer
 cmd.Stderr=&stderr
 data,err:=cmd.Output()
 if err!=nil{return nil,fmt.Errorf("err: %v: stderr: %s",err,stderr.String())}
 dec:=json.NewDecoder(bytes.NewReader(data))
 names:=map[string]string{}
 var pkgs []packageInfo
 for {
  var p packageInfo
  err=dec.Decode(&p)
  if err==io.EOF{break};if err!=nil{return nil,err}
  pkgs=append(pkgs,p)
  if p.Name!=""{names[p.ImportPath]=p.Name}
 }
 seen:=map[string]bool{}
 var errors []*packageError
 for _,p:=range pkgs{if p.Error!=nil{errors=append(errors,p.Error)}}
 // Some toolchain failures are recorded only on the root package.
 if len(pkgs)>0{errors=append(errors,pkgs[len(pkgs)-1].DepsErrors...)}
 bad:=false
 for _,e:=range errors{
  key:=e.Pos+"\n"+e.Err
  if seen[key]{continue};seen[key]=true
  msg:=e.Err
  if stdin && strings.HasPrefix(msg,"no Go files in "){msg="no Go files in"}
  pos:=e.Pos
  if pos=="" {pos="-"} else {
   abs,_:=filepath.Abs(dir)
   pos=strings.TrimPrefix(pos,abs+string(os.PathSeparator))
  }
  fmt.Fprintf(os.Stderr,"%s: %s\n",pos,msg)
  bad=true
 }
 if bad{return nil,fmt.Errorf("package has an errors")}
 return names,nil
}
