type modLine struct { number int; words []string }

// Lex just the manifest language: double-quoted words, line comments, and
// directive blocks.  Keeping lines separate gives useful, precise diagnostics.
func lexModule(data []byte)([]modLine,error){
 lines:=strings.Split(string(data),"\n")
 out:=make([]modLine,0,len(lines))
 for i,text:=range lines {
  var words []string
  r:=[]rune(strings.TrimSuffix(text,"\r"))
  for p:=0;p<len(r); {
   if r[p]==' ' || r[p]=='\t' || r[p]=='\r'{p++;continue}
   if r[p]=='/' && p+1<len(r) && r[p+1]=='/'{break}
   if r[p]=='/' && p+1<len(r) && r[p+1]=='*'{return nil,fmt.Errorf("go.mod:%d: mod files must use // comments (not /* */ comments)",i+1)}
   if r[p]=='\ufeff' || (unicode.IsControl(r[p]) && r[p]!='\t') {return nil,fmt.Errorf("go.mod:%d: unexpected input character %q",i+1,r[p])}
   start:=p
   if r[p]=='"' {
    p++
    for p<len(r) && r[p]!='"'{if r[p]=='\\'{p++};p++}
    if p>=len(r){return nil,fmt.Errorf("go.mod:%d: unexpected newline in string",i+1)}
    p++
   } else if r[p]=='(' || r[p]==')'{p++} else {
    for p<len(r) && r[p]!=' ' && r[p]!='\t' && r[p]!='\r' && r[p]!='(' && r[p]!=')'{
     if r[p]=='/' && p+1<len(r) && (r[p+1]=='/' || r[p+1]=='*'){break}
     p++
    }
   }
   if start==p{p++}
   words=append(words,string(r[start:p]))
  }
  out=append(out,modLine{i+1,words})
 }
 return out,nil
}

var goVersionPattern=regexp.MustCompile(`^[0-9]+\.[0-9]+(\.[0-9]+)?([a-z]+[0-9]+)?$`)
var modVersionPattern=regexp.MustCompile(`^v[0-9]+(\.[0-9]+)?(\.[0-9]+)?(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$`)

func moduleName(data []byte)(string,error){
 lines,err:=lexModule(data);if err!=nil{return "",err}
 var name string
 var problems []string
 seen:=map[string]bool{}
 block:="";blockLine:=0
 issue:=func(line int,msg string){problems=append(problems,fmt.Sprintf("go.mod:%d: %s",line,msg))}
 parseString:=func(word string)(string,error){
  if strings.HasPrefix(word,"\""){
   value,err:=strconv.Unquote(word);if err!=nil{return "",fmt.Errorf("invalid quoted string: %v",err)};return value,nil
  }
  if strings.ContainsAny(word,"\"'`"){return "",fmt.Errorf("invalid quoted string: unquoted string cannot contain quote")}
  return word,nil
 }
 for _,line:=range lines{
  words:=line.words
  if len(words)==0{continue}
  directive:=""
  if block!=""{
   if words[0]==")"{block="";continue}
   directive=block
  }else{
   directive=words[0];words=words[1:]
   if len(words)==1 && words[0]=="("{block=directive;blockLine=line.number;continue}
  }
  parsed:=make([]string,len(words));valid:=true
  for i,w:=range words{
   parsed[i],err=parseString(w)
   if err!=nil{issue(line.number,err.Error());valid=false;break}
  }
  if !valid{continue}
  words=parsed
  switch directive{
  case "module":
   if seen[directive]{issue(line.number,"repeated module statement");continue}
   if len(words)!=1{issue(line.number,"usage: module module/path");continue}
   name=words[0];seen[directive]=true
  case "go":
   if seen[directive]{issue(line.number,"repeated go statement");continue}
   if len(words)!=1{issue(line.number,"go directive expects exactly one argument");continue}
   if !goVersionPattern.MatchString(words[0]){issue(line.number,fmt.Sprintf("invalid go version '%s': must match format 1.23.0",words[0]));continue}
   seen[directive]=true
  case "toolchain":
   if seen[directive]{issue(line.number,"repeated toolchain statement");continue}
   if len(words)!=1{issue(line.number,"toolchain directive expects exactly one argument");continue}
   if words[0]!="default" && !strings.HasPrefix(words[0],"go1."){issue(line.number,fmt.Sprintf("invalid toolchain version '%s': must match format go1.23.0 or default",words[0]));continue}
   seen[directive]=true
  case "require", "exclude":
   if len(words)!=2{issue(line.number,"usage: "+directive+" module/path v1.2.3");continue}
   if !modVersionPattern.MatchString(words[1]){issue(line.number,fmt.Sprintf("%s %s: version %q invalid: must be of the form v1.2.3",directive,words[0],words[1]));continue}
  case "replace":
   arrow:=-1
   for i,w:=range words{if w=="=>"{arrow=i}}
   if arrow<1 || arrow>2 || len(words)-arrow<2 || len(words)-arrow>3{issue(line.number,"usage: replace module/path [v1.2.3] => other/module v1.4\n\t or replace module/path [v1.2.3] => ../local/directory")}
  case "retract":
   if len(words)==0{issue(line.number,"usage: retract version | [version, version]")}
  case "godebug":
   if len(words)!=1 || !strings.Contains(words[0],"="){issue(line.number,"usage: godebug key=value")}
  case "tool":
   if len(words)!=1{issue(line.number,"usage: tool package/path")}
  case "ignore":
   if len(words)!=1{issue(line.number,"usage: ignore directory/path")}
  default:
   issue(line.number,"unknown directive: "+directive)
  }
 }
 if block!=""{issue(len(lines),fmt.Sprintf("syntax error (unterminated block started at go.mod:%d:1)",blockLine))}
 if len(problems)>0{return "",fmt.Errorf("%s",strings.Join(problems,"\n"))}
 if !seen["module"]{return "",fmt.Errorf("module is undefined")}
 return name,nil
}
